def group_states(grid, goal, start):
    # Define possible movements (up, down, left, right)
    movements = [(0, -1), (0, 1), (-1, 0), (1, 0)]

    # Function to check if a cell is within the grid boundaries
    def is_valid(x, y):
        return 0 <= x < len(grid) and 0 <= y < len(grid[0])

    # Function to get the abstract state of a cell
    def get_abstract_state(x, y):
        # If the cell is the goal or contains an obstacle, it's its own abstract state
        if grid[x][y] == "X" or grid[x][y] == goal:
            return str(grid[x][y])

        # Otherwise, check all possible movements from this cell
        neighbors = []
        for dx, dy in movements:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny) and grid[nx][ny] != "X":
                neighbors.append(get_abstract_state(nx, ny))

        # Sort the neighbors to ensure consistency
        neighbors.sort()

        # Return a string representing this cell's abstract state
        return ",".join(neighbors)

    # Group states into abstract states based on their optimal actions and expected value
    abstract_states = {}
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] != "X":
                abstract_state = get_abstract_state(i, j)
                if abstract_state not in abstract_states:
                    abstract_states[abstract_state] = []
                abstract_states[abstract_state].append(grid[i][j])

    # Return the grouping of states into abstract states
    return list(abstract_states.values())


# Example usage:
grid = [[0, 2, 4, 8, 10], [1, "X", 7, "X", 12], [3, 6, "X", 18, 14], [5, "X", 15, "X", 17], [9, 11, 13, 16, 19]]
